// Only runs if user is non-null
user?.let { nonNullUser ->
    sendEmail(nonNullUser.email)
    logLogin(nonNullUser.id)
}

// Transform and return
val upperName = name?.let { it.trim().uppercase() }

// Without apply
val button = Button(context)
button.text = "Click me"
button.isEnabled = true
button.setOnClickListener { handleClick() }

// With apply — cleaner
val button = Button(context).apply {
    text = "Click me"
    isEnabled = true
    setOnClickListener { handleClick() }
}

fun getUser(): User =
    repository.findUser(id)
        .also { println("Found user: $it") }  // log
        .also { require(it.isActive) }              // validate

// Great for debugging chains
listOf(1, 2, 3)
    .map { it * 2 }
    .also { println("After map: $it") }  // [2, 4, 6]
    .filter { it > 3 }
    .also { println("After filter: $it") }  // [4, 6]

// Extension form: 'this' is the object, the result is the last expression
val status = service.run {
    port = 8080
    connect()          // returned
}

// No receiver: a scoped block that produces a value
val label = run {
    val base = computeBase()
    val tax = base * 0.2
    "Total: ${base + tax}"   // 'base' and 'tax' don't leak out
}

val summary = with(order) {
    "$id: ${items.size} items, total $total"   // id, items, total belong to order
}

// with a builder-like object
with(paint) {
    color = Color.RED
    strokeWidth = 4f
    isAntiAlias = true
}

val port = config.port.takeIf { it in 1..65535 } ?: 8080

val text = File(path)
    .takeIf { it.exists() && it.length() > 0 }
    ?.readText()

val name = input.trim().takeUnless { it.isEmpty() }

// Bug: showLogin() also runs for a logged-in user without an avatar
user?.let { it.avatarUrl } ?: showLogin()

// Clear: two explicit branches
if (user != null) {
    show(user.avatarUrl)
} else {
    showLogin()
}

// Hard to read: which 'it' is which?
order?.let {
    it.customer?.let {
        show(it.name)           // this 'it' is the customer, the order is hidden
    }
}

// Clearer: named parameters
order?.let { o ->
    o.customer?.let { c -> show(c.name, o.id) }
}

// Needless wrapping
name.let { println(it) }

// Just call it
println(name)

// Worth it: the temporary stays inside and the null check is one line
val length = name?.let { it.trim().length }
